export { mergeProps } from "./merge-props"
export { normalizeProps, toStyleString } from "./normalize-props"
export { spreadProps, type Attrs } from "./spread-props"
export { VanillaMachine } from "./machine"
import type { Bindable, BindableParams } from "@zag-js/core"
import { proxy } from "@zag-js/store"
import { isFunction } from "@zag-js/utils"

export function bindable<T>(props: () => BindableParams<T>): Bindable<T> {
  const initial = props().value ?? props().defaultValue

  if (props().debug) {
    console.log(`[bindable > ${props().debug}] initial`, initial)
  }

  const eq = props().isEqual ?? Object.is

  const store = proxy({ value: initial as T })

  const controlled = () => props().value !== undefined

  return {
    initial,
    ref: store,
    get() {
      return controlled() ? (props().value as T) : store.value
    },
    set(nextValue: T | ((prev: T) => T)) {
      const prev = controlled() ? (props().value as T) : store.value
      const next = isFunction(nextValue) ? nextValue(prev as T) : nextValue

      if (props().debug) {
        console.log(`[bindable > ${props().debug}] setValue`, { next, prev })
      }

      if (!controlled()) store.value = next
      if (!eq(next, prev)) {
        props().onChange?.(next, prev)
      }
    },
    invoke(nextValue: T, prevValue: T) {
      props().onChange?.(nextValue, prevValue)
    },
    hash(value: T) {
      return props().hash?.(value) ?? String(value)
    },
  }
}

bindable.cleanup = (_fn: VoidFunction) => {
  // No-op in vanilla: cleanup is handled manually via machine.stop()
}

bindable.ref = <T>(defaultValue: T) => {
  let value = defaultValue
  return {
    get: () => value,
    set: (next: T) => {
      value = next
    },
  }
}
export interface Attrs {
  [key: string]: any
}

const prevAttrsMap = new WeakMap<Element, Map<string, Attrs>>()

const assignableProps = new Set<string>(["value", "checked", "selected"])

// SVG attributes that need to preserve case
const caseSensitiveSvgAttrs = new Set<string>([
  "viewBox",
  "preserveAspectRatio",
  "clipPath",
  "clipRule",
  "fillRule",
  "strokeWidth",
  "strokeLinecap",
  "strokeLinejoin",
  "strokeDasharray",
  "strokeDashoffset",
  "strokeMiterlimit",
])

// Check if element is SVG
const isSvgElement = (node: Element): boolean => {
  return node.tagName === "svg" || node.namespaceURI === "http://www.w3.org/2000/svg"
}

// Get the correct attribute name, preserving case for SVG attributes
const getAttributeName = (node: Element, attrName: string): string => {
  const shouldPreserveCase = isSvgElement(node) && caseSensitiveSvgAttrs.has(attrName)
  return shouldPreserveCase ? attrName : attrName.toLowerCase()
}

const toCssProperty = (key: string) =>
  key.startsWith("--") ? key : key.replace(/[A-Z]/g, (match) => `-${match.toLowerCase()}`)

// Patches inline styles property by property (like the react adapter) so that styles written
// directly to the element by other code - popper's `--x`/`--y`, the layer stack's `--layer-index` -
// are not wiped when an unrelated style property changes.
const applyStyle = (node: Element, prevStyle: unknown, nextStyle: unknown): void => {
  // a raw string means the caller owns the whole attribute
  if (typeof nextStyle === "string") {
    node.setAttribute("style", nextStyle)
    return
  }

  if (nextStyle == null && typeof prevStyle === "string") {
    node.removeAttribute("style")
    return
  }

  const style = (node as HTMLElement).style
  if (style == null) return

  for (const key in prevStyle as Attrs) {
    if ((nextStyle as Attrs)?.[key] == null) style.removeProperty(toCssProperty(key))
  }

  for (const key in nextStyle as Attrs) {
    const value = (nextStyle as Attrs)[key]
    if (value == null) style.removeProperty(toCssProperty(key))
    else style.setProperty(toCssProperty(key), String(value))
  }
}

export function spreadProps(node: Element, attrs: Attrs, machineId?: string): () => void {
  const scopeKey = machineId || "default"

  let machineMap = prevAttrsMap.get(node)
  if (!machineMap) {
    machineMap = new Map<string, Attrs>()
    prevAttrsMap.set(node, machineMap)
  }

  const oldAttrs = machineMap.get(scopeKey) || {}

  const attrKeys = Object.keys(attrs)

  const addEvt = (e: string, f: EventListener) => {
    node.addEventListener(e.toLowerCase(), f)
  }

  const remEvt = (e: string, f: EventListener) => {
    node.removeEventListener(e.toLowerCase(), f)
  }

  const onEvents = (attr: string) => attr.startsWith("on")
  const others = (attr: string) => !attr.startsWith("on")

  const setup = (attr: string) => addEvt(attr.substring(2), attrs[attr])
  const teardown = (attr: string) => remEvt(attr.substring(2), attrs[attr])

  const apply = (attrName: string) => {
    const value = attrs[attrName]

    const oldValue = oldAttrs[attrName]
    if (value === oldValue) return

    // Handle class as property (faster than setAttribute)
    if (attrName === "class") {
      ;(node as HTMLElement).className = value ?? ""
      return
    }

    // Handle style as individual properties (never as a whole attribute)
    if (attrName === "style") {
      applyStyle(node, oldValue, value)
      return
    }

    // Handle DOM properties (value, checked, etc.) - must come before boolean check
    if (assignableProps.has(attrName)) {
      ;(node as any)[attrName] = value ?? ""
      return
    }

    // Handle boolean attributes with toggleAttribute (for non-property booleans like disabled, hidden)
    // Also skip aria- attributes to preserve their string values
    if (typeof value === "boolean" && !attrName.includes("aria-")) {
      ;(node as HTMLElement).toggleAttribute(getAttributeName(node, attrName), value)
      return
    }

    // Special handling for children attribute
    if (attrName === "children") {
      node.innerHTML = value
      return
    }

    if (value != null) {
      node.setAttribute(getAttributeName(node, attrName), value)
      return
    }

    node.removeAttribute(getAttributeName(node, attrName))
  }

  // reconcile old attributes (must match apply logic)
  for (const key in oldAttrs) {
    if (attrs[key] == null) {
      if (key === "class") {
        ;(node as HTMLElement).className = ""
      } else if (key === "style") {
        applyStyle(node, oldAttrs[key], undefined)
      } else if (assignableProps.has(key)) {
        ;(node as any)[key] = ""
      } else {
        node.removeAttribute(getAttributeName(node, key))
      }
    }
  }

  const oldEvents = Object.keys(oldAttrs).filter(onEvents)
  oldEvents.forEach((evt) => {
    remEvt(evt.substring(2), oldAttrs[evt])
  })

  attrKeys.filter(onEvents).forEach(setup)
  attrKeys.filter(others).forEach(apply)

  machineMap.set(scopeKey, attrs)

  return function cleanup() {
    attrKeys.filter(onEvents).forEach(teardown)
    const currentMachineMap = prevAttrsMap.get(node)
    if (currentMachineMap) {
      currentMachineMap.delete(scopeKey)
      if (currentMachineMap.size === 0) {
        prevAttrsMap.delete(node)
      }
    }
  }
}

import type {
  ActionsOrFn,
  Bindable,
  BindableContext,
  BindableRefs,
  ChooseFn,
  ComputedFn,
  EffectsOrFn,
  GuardFn,
  Machine,
  MachineSchema,
  Params,
  PropFn,
  Scope,
  Service,
  Transition,
} from "@zag-js/core"
import {
  createReplaceTracker,
  createScope,
  findTransition,
  getExitEnterStates,
  hasTag,
  INIT_STATE,
  MachineStatus,
  matchesState,
  resolveStateValue,
} from "@zag-js/core"
import { subscribe } from "@zag-js/store"
import {
  callAll,
  compact,
  ensure,
  identity,
  isEqual,
  isFunction,
  isString,
  runIfFn,
  toArray,
  warn,
} from "@zag-js/utils"
import { bindable } from "./bindable"
import { createRefs } from "./refs"
import { mergeMachineProps } from "./merge-machine-props"

export class VanillaMachine<T extends MachineSchema> {
  scope: Scope
  context: BindableContext<T>
  prop: PropFn<T>
  state: Bindable<T["state"]>
  refs: BindableRefs<T>
  computed: ComputedFn<T>

  private event: T["event"] = { type: "" } as T["event"]
  private previousEvent: T["event"] = { type: "" } as T["event"]

  private effects = new Map<string, VoidFunction>()
  private replaceTracker = createReplaceTracker()
  private transition: Transition<T> | null = null

  private cleanups: VoidFunction[] = []
  private subscriptions: Array<(service: Service<T>) => void> = []

  private userPropsRef: { current: Partial<T["props"]> | (() => Partial<T["props"]>) }

  private getEvent = () => ({
    ...this.event,
    current: () => this.event,
    previous: () => this.previousEvent,
  })

  private getState = () => ({
    ...this.state,
    matches: (...values: T["state"][]) =>
      values.some((value) => matchesState(this.state.get() as string, value as string)),
    hasTag: (tag: T["tag"]) => hasTag(this.machine, this.state.get(), tag),
  })

  private debug = (...args: any[]) => {
    if (this.machine.debug) console.log(...args)
  }

  private notify = () => {
    this.publish()
  }

  constructor(
    private machine: Machine<T>,
    userProps: Partial<T["props"]> | (() => Partial<T["props"]>) = {},
  ) {
    this.userPropsRef = { current: userProps }

    // create scope
    const { id, ids, getRootNode } = runIfFn(userProps) as any
    this.scope = createScope({ id, ids, getRootNode })

    // create prop
    const prop: PropFn<T> = (key) => {
      const __props = runIfFn(this.userPropsRef.current)
      const props: any = machine.props?.({ props: compact(__props), scope: this.scope }) ?? __props
      return props[key] as any
    }
    this.prop = prop

    // create context
    const context: any = machine.context?.({
      prop,
      bindable,
      scope: this.scope,
      flush(fn: VoidFunction) {
        queueMicrotask(fn)
      },
      getContext() {
        return ctx as any
      },
      getComputed() {
        return computed as any
      },
      getRefs() {
        return refs as any
      },
      getEvent: this.getEvent.bind(this),
    })

    // subscribe to context changes
    if (context) {
      Object.values(context).forEach((item: any) => {
        const unsub = subscribe(item.ref, () => this.notify())
        this.cleanups.push(unsub)
      })
    }

    // context function
    const ctx: BindableContext<T> = {
      get(key) {
        return context?.[key].get()
      },
      set(key, value) {
        context?.[key].set(value)
      },
      initial(key) {
        return context?.[key].initial
      },
      hash(key) {
        const current = context?.[key].get()
        return context?.[key].hash(current)
      },
    }
    this.context = ctx

    const computed: ComputedFn<T> = (key) => {
      ensure(machine.computed, () => `[zag-js] No computed object found on machine`)
      return machine.computed[key]({
        context: ctx as any,
        event: this.getEvent(),
        prop,
        refs: this.refs,
        scope: this.scope,
        computed: computed as any,
      })
    }
    this.computed = computed

    const refs: BindableRefs<T> = createRefs(machine.refs?.({ prop, context: ctx }) ?? {})
    this.refs = refs

    // state
    const state = bindable(() => ({
      defaultValue: resolveStateValue(machine, machine.initialState({ prop })),
      onChange: (nextState, prevState) => {
        const { exiting, entering } = getExitEnterStates(this.machine, prevState, nextState, this.transition?.reenter)

        exiting.forEach((item) => {
          const exitEffects = this.effects.get(item.path)
          exitEffects?.()
          this.effects.delete(item.path)
        })

        exiting.forEach((item) => {
          this.action(item.state?.exit)
        })

        this.action(this.transition?.actions)

        entering.forEach((item) => {
          const cleanup = this.effect(item.state?.effects)
          if (cleanup) {
            const existing = this.effects.get(item.path)
            this.effects.set(item.path, existing ? callAll(existing, cleanup) : cleanup)
          }
        })

        if (prevState === INIT_STATE) {
          this.action(machine.entry)
          const cleanup = this.effect(machine.effects)
          if (cleanup) {
            const existing = this.effects.get(INIT_STATE)
            this.effects.set(INIT_STATE, existing ? callAll(existing, cleanup) : cleanup)
          }
        }

        entering.forEach((item) => {
          this.action(item.state?.entry)
        })
      },
    }))
    this.state = state
    this.cleanups.push(subscribe(this.state.ref, () => this.notify()))
  }

  updateProps(newProps: Partial<T["props"]> | (() => Partial<T["props"]>)) {
    const prevSource = this.userPropsRef.current

    this.userPropsRef.current = () => {
      const prev = runIfFn(prevSource)
      const next = runIfFn(newProps)
      return mergeMachineProps(prev, next)
    }

    this.notify()
  }

  send = (event: T["event"]) => {
    if (this.status !== MachineStatus.Started) return

    const key = event?.replaces
    const token = key ? this.replaceTracker.claim(key) : undefined

    queueMicrotask(() => {
      if (!event) return
      if (key && token && this.replaceTracker.isReplaced(key, token)) return

      this.previousEvent = this.event
      this.event = event

      this.debug("send", event)

      let currentState = this.state.get()

      const eventType = event.type as string
      const { transitions, source } = findTransition(this.machine, currentState, eventType)
      const transition = this.choose(transitions)
      if (!transition) return

      // save current transition
      this.transition = transition
      const target = resolveStateValue(this.machine, transition.target ?? currentState, source)

      this.debug("transition", transition)

      const changed = target !== currentState
      if (changed) {
        // state change is high priority
        this.state.set(target)
      } else if (transition.reenter) {
        // reenter will re-invoke the current state
        this.state.invoke(currentState, currentState)
      } else {
        // call transition actions
        this.action(transition.actions)
      }
    })
  }

  private action = (keys: ActionsOrFn<T> | undefined) => {
    const strs = isFunction(keys) ? keys(this.getParams()) : keys
    if (!strs) return
    const fns = strs.map((s) => {
      const fn = this.machine.implementations?.actions?.[s]
      if (!fn) warn(`[zag-js] No implementation found for action "${JSON.stringify(s)}"`)
      return fn
    })
    for (const fn of fns) {
      fn?.(this.getParams())
    }
  }

  private guard = (str: T["guard"] | GuardFn<T>) => {
    if (isFunction(str)) return str(this.getParams())
    const fn = this.machine.implementations?.guards?.[str]
    if (!fn) warn(`[zag-js] No implementation found for guard "${JSON.stringify(str)}"`)
    return fn?.(this.getParams())
  }

  private effect = (keys: EffectsOrFn<T> | undefined) => {
    const strs = isFunction(keys) ? keys(this.getParams()) : keys
    if (!strs) return
    const fns = strs.map((s) => {
      const fn = this.machine.implementations?.effects?.[s]
      if (!fn) warn(`[zag-js] No implementation found for effect "${JSON.stringify(s)}"`)
      return fn
    })
    const cleanups: VoidFunction[] = []
    for (const fn of fns) {
      const cleanup = fn?.(this.getParams())
      if (cleanup) cleanups.push(cleanup)
    }
    return () => cleanups.forEach((fn) => fn?.())
  }

  private choose: ChooseFn<T> = (transitions) => {
    return toArray(transitions).find((t: any) => {
      let result = !t.guard
      if (isString(t.guard)) result = !!this.guard(t.guard)
      else if (isFunction(t.guard)) result = t.guard(this.getParams())
      return result
    })
  }

  start() {
    this.status = MachineStatus.Started
    this.debug("initializing...")
    this.state.invoke(this.state.initial!, INIT_STATE)
    this.setupTrackers()
  }

  stop() {
    // run exit effects
    this.effects.forEach((fn) => fn?.())
    this.effects.clear()
    this.transition = null
    this.action(this.machine.exit)

    // unsubscribe from all subscriptions
    this.cleanups.forEach((unsub) => unsub())
    this.cleanups = []
    this.subscriptions = []

    this.status = MachineStatus.Stopped
    this.debug("unmounting...")
  }

  subscribe = (fn: (service: Service<T>) => void) => {
    this.subscriptions.push(fn)
    return () => {
      const index = this.subscriptions.indexOf(fn)
      if (index > -1) this.subscriptions.splice(index, 1)
    }
  }

  private status = MachineStatus.NotStarted

  get service(): Service<T> {
    return {
      state: this.getState(),
      send: this.send,
      context: this.context,
      prop: this.prop,
      scope: this.scope,
      refs: this.refs,
      computed: this.computed,
      event: this.getEvent(),
      getStatus: () => this.status,
    } as Service<T>
  }

  private publish = () => {
    this.callTrackers()
    this.subscriptions.forEach((fn) => fn(this.service))
  }

  private trackers: { deps: any[]; fn: any }[] = []

  private setupTrackers = () => {
    this.machine.watch?.(this.getParams())
  }

  private callTrackers = () => {
    this.trackers.forEach(({ deps, fn }) => {
      const next = deps.map((dep) => dep())
      if (!isEqual(fn.prev, next)) {
        fn()
        fn.prev = next
      }
    })
  }

  getParams = (): Params<T> =>
    ({
      state: this.getState(),
      context: this.context,
      event: this.getEvent(),
      prop: this.prop,
      send: this.send,
      action: this.action,
      guard: this.guard,
      track: (deps: any[], fn: any) => {
        fn.prev = deps.map((dep) => dep())
        this.trackers.push({ deps, fn })
      },
      refs: this.refs,
      computed: this.computed,
      flush: identity,
      scope: this.scope,
      choose: this.choose,
    }) as Params<T>
}
